package com.itemstatsfilter;

import java.awt.Color;

/**
 * Indicator color schemes. Declaration order is the dropdown order.
 * Each preset holds one color per {@link HideReason}, in the same order.
 */
public enum ColorScheme
{
	GREY("Grey", LightGray.VALUE, LightGray.VALUE, LightGray.VALUE),
	MAGMA("Magma", new Color(0xED5A5F), new Color(0xFD9668), new Color(0xFDE7A9)),
	VIRIDIS("Viridis", new Color(0x2A9DB0), new Color(0x4EC36B), new Color(0xECE51B)),
	CUSTOM("Custom", LightGray.VALUE, LightGray.VALUE, LightGray.VALUE);

	/**
	 * The marker color used before color schemes existed (Color.LIGHT_GRAY, #C0C0C0).
	 */
	static final Color LIGHT_GRAY = LightGray.VALUE;

	private final String displayName;
	private final Color hiddenList;
	private final Color rule;
	private final Color hold;

	ColorScheme(String displayName, Color hiddenList, Color rule, Color hold)
	{
		this.displayName = displayName;
		this.hiddenList = hiddenList;
		this.rule = rule;
		this.hold = hold;
	}

	/**
	 * This preset's fixed color for a hiding method. Custom's colors come from the config instead.
	 */
	Color color(HideReason reason)
	{
		switch (reason)
		{
			case HIDDEN_LIST:
				return hiddenList;
			case RULE:
				return rule;
			default:
				return hold;
		}
	}

	@Override
	public String toString()
	{
		return displayName;
	}

	// Enum constants can't refer to the enum's own static fields in their constructors
	private static final class LightGray
	{
		private static final Color VALUE = new Color(192, 192, 192);
	}
}

