package com.itemstatsfilter;

import java.util.List;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.util.Text;

/**
 * Why an item's stats are hidden, highest priority first. When more than one applies,
 * the first one decides the indicator's color and whether rule indicators apply.
 */
enum HideReason
{
	HIDDEN_LIST,
	RULE,
	HOLD;

	/**
	 * The highest-priority reason that applies, or null if the stats aren't hidden.
	 */
	static HideReason pick(boolean hiddenList, boolean rule, boolean hold)
	{
		if (hiddenList)
		{
			return HIDDEN_LIST;
		}
		if (rule)
		{
			return RULE;
		}
		return hold ? HOLD : null;
	}

	/**
	 * Whether the tooltips Item Stats added for an item are a single tooltip whose only
	 * line is the item's weight. Item Stats separates lines with "&lt;/br&gt;" and colors
	 * values with tags, so lines are split first and tags removed after.
	 */
	static boolean isWeightOnly(List<Tooltip> itemStatsTooltips)
	{
		if (itemStatsTooltips.size() != 1)
		{
			return false;
		}

		final String text = itemStatsTooltips.get(0).getText();
		if (text == null)
		{
			return false;
		}

		int lines = 0;
		for (String line : text.split("</br>"))
		{
			final String plain = Text.removeTags(line).trim();
			if (plain.isEmpty())
			{
				continue;
			}
			if (!plain.startsWith("Weight:"))
			{
				return false;
			}
			lines++;
		}
		return lines > 0;
	}
}

