	String HOTKEY = "hotkey";
	String RULE_WEIGHT_ONLY = "ruleWeightOnly";
	String RULE_INDICATORS = "ruleIndicators";
	String ALWAYS_SHOW_ITEMS = "alwaysShowItems";

	@ConfigSection(
		name = "Indicator colors",
		description = "Colors for the hidden-stats indicator, one per way of hiding stats",
		position = 3,
		closedByDefault = true
	)
	String colorsSection = "colorsSection";

	@ConfigSection(
		name = "Hold to show",
		description = "Use a held key to show item stats, including stats of hidden items",
		position = 10
	)
	String hotkeySection = "hotkeySection";

	@ConfigSection(
		name = "Rules",
		description = "Hide kinds of stats tooltips automatically. Every rule is off by default.",
		position = 20,
		closedByDefault = true
	)
	String rulesSection = "rulesSection";

	@ConfigSection(
		name = "Always show",
		description = "Items whose stats are never hidden",
		position = 30,
		closedByDefault = true
	)
	String alwaysShowSection = "alwaysShowSection";

	@ConfigItem(
		keyName = HIDDEN_ITEMS,
		name = "Hidden items",
		description = "Items that never show a stat tooltip. Comma-separated names, * is a wildcard (e.g. Prayer potion*)",
		position = 0
	)
	default String hiddenItems()
	{
		return "";
	}

	@ConfigItem(
		keyName = "shiftClickToggle",
		name = "Shift-click option",
		description = "Shift + right-click an item to get a 'Hide stats' / 'Show stats' option that edits the Hidden items and Always show lists",
		position = 1
	)
	default boolean shiftClickToggle()
	{
		return true;
	}

	@ConfigItem(
		keyName = INDICATOR,
		name = "Indicator",
		description = "How to mark an item whose stats are hidden. Asterisk adds * after the item name in the Mouse Tooltips box (that plugin must be on).",
		position = 2
	)
	default HiddenStatsIndicator hiddenIndicator()
	{
		return HiddenStatsIndicator.MARKER_BOX;
	}

	@ConfigItem(
		keyName = COLOR_SCHEME,
		name = "Color scheme",
		description = "Colors for items hidden by the Hidden items list, a rule, and hold mode. "
			+ "Grey keeps the standard look. Magma: #ED5A5F, #FD9668, #FDE7A9. "
			+ "Viridis: #2A9DB0, #4EC36B, #ECE51B. Custom uses the three colors below.",
		position = 4,
		section = colorsSection
	)
	default ColorScheme colorScheme()
	{
		return ColorScheme.GREY;
	}

	@ConfigItem(
		keyName = "customHiddenList",
		name = "Custom hidden list",
		description = "Used only when Color scheme is Custom. Marks items hidden by the Hidden items list.",
		position = 5,
		section = colorsSection
	)
	default Color customHiddenList()
	{
		return ColorScheme.LIGHT_GRAY;
	}

	@ConfigItem(
		keyName = "customRule",
		name = "Custom rule",
		description = "Used only when Color scheme is Custom. Marks items hidden by a rule.",
		position = 6,
		section = colorsSection
	)
	default Color customRule()
	{
		return ColorScheme.LIGHT_GRAY;
	}

	@ConfigItem(
		keyName = "customHold",
		name = "Custom hold-to-show",
		description = "Used only when Color scheme is Custom. Marks items hidden by Only show item stats on hold.",
		position = 7,
		section = colorsSection
	)
	default Color customHold()
	{
		return ColorScheme.LIGHT_GRAY;
	}

	@ConfigItem(
		keyName = REQUIRE_HOTKEY,
		name = "Only show item stats on hold",
		description = "Only show stat tooltips while the key below is held down",
		position = 11,
		section = hotkeySection
	)
	default boolean requireHotkey()
	{
		return false;
	}

	@ConfigItem(
		keyName = SHOW_HIDDEN_ON_HOLD,
		name = "Show hidden item stats on hold",
		description = "While the key below is held, also show stats for items hidden by the Hidden items list or a rule",
		position = 12,
		section = hotkeySection
	)
	default boolean showHiddenOnHold()
	{
		return true;
	}

	@ConfigItem(
		keyName = HOTKEY,
		name = "Key",
		description = "Key to hold. Ctrl or Alt work best: Shift also turns left-click into Drop if shift-click drop is on, and a non-modifier key can't be typed while it's bound.",
		position = 13,
		section = hotkeySection
	)
	default Keybind hotkey()
	{
		return Keybind.CTRL;
	}

	@ConfigItem(
		keyName = RULE_WEIGHT_ONLY,
		name = "Hide weight-only tooltips",
		description = "Hide the stats tooltip when its only line is the item's weight, as with a tinderbox. Needs Item Stats' Show weight on.",
		position = 21,
		section = rulesSection
	)
	default boolean ruleWeightOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = RULE_INDICATORS,
		name = "Show rule-hidden indicators",
		description = "Show the indicator on items hidden by a rule. Items on the Hidden items list keep theirs either way.",
		position = 22,
		section = rulesSection
	)
