		name = "Always-shown items",
		description = "Items whose stats are never hidden, overriding the Hidden items list, rules and hold mode. Comma-separated names, * is a wildcard.",
		position = 31,
		section = alwaysShowSection
	)
	default String alwaysShowItems()
	{
		return "";
	}
