@PluginDescriptor(
	name = "Item Stats Filter",
	description = "Hide Item Stats tooltips by filter, rule or hotkey",
	tags = {"item", "stats", "tooltip", "hide", "blacklist", "hotkey", "equipment", "filter", "rule"}
)
public class ItemStatsFilterPlugin extends Plugin
{
	private static final String HIDE_OPTION = "Hide stats";
	private static final String SHOW_OPTION = "Show stats";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TooltipManager tooltipManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ItemStatsFilterConfig config;

	private ItemStatsFilterOverlay overlay;

	// While running, these are only used on the client thread (overlay rendering, menu
	// events, and config changes routed through clientThread.invoke).
	private volatile List<String> hiddenPatterns = Collections.emptyList();
	private final Map<Integer, Boolean> hiddenCache = new HashMap<>();
	private volatile List<String> alwaysShowPatterns = Collections.emptyList();
	private final Map<Integer, Boolean> alwaysShowCache = new HashMap<>();

	// The weight-only rule needs the tooltip Item Stats builds, which can't be built while a
	// menu is open. The overlay records the last hovered item's result for the shift-click menu.
	private int lastRuleItemId = -1;
	private boolean lastRuleMatch;

	private HotkeyListener hotkeyListener;
	private volatile boolean hotkeyHeld;

	@Provides
	ItemStatsFilterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ItemStatsFilterConfig.class);
	}

	@Override
	protected void startUp()
	{
		if (overlay == null)
		{
			overlay = new ItemStatsFilterOverlay(this, tooltipManager, createItemStatsProbe());
		}

		updateHiddenPatterns();
		updateAlwaysShowPatterns();
		updateHotkeyListener();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		synchronized (this)
		{
			if (hotkeyListener != null)
			{
				keyManager.unregisterKeyListener(hotkeyListener);
				hotkeyListener = null;
			}
		}
		hotkeyHeld = false;
		lastRuleItemId = -1;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ItemStatsFilterConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case ItemStatsFilterConfig.HIDDEN_ITEMS:
				clientThread.invoke(() ->
				{
					updateHiddenPatterns();
					// The list going empty or non-empty can change whether the key does anything
					if (wantsHotkey() != (hotkeyListener != null))
					{
						updateHotkeyListener();
					}
				});
				break;
			case ItemStatsFilterConfig.ALWAYS_SHOW_ITEMS:
				clientThread.invoke(this::updateAlwaysShowPatterns);
				break;
			case ItemStatsFilterConfig.REQUIRE_HOTKEY:
			case ItemStatsFilterConfig.SHOW_HIDDEN_ON_HOLD:
			case ItemStatsFilterConfig.HOTKEY:
			case ItemStatsFilterConfig.RULE_WEIGHT_ONLY:
				updateHotkeyListener();
				break;
		}
	}

	/**
	 * Shift + right-click on an item adds "Hide stats" / "Show stats" just below Examine.
	 * Everything is judged as if the hold key weren't held, so the option reflects the
	 * item's lasting state rather than what the key is doing right now.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!config.shiftClickToggle() || !client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		final MenuEntry[] entries = event.getMenuEntries();
		for (int idx = entries.length - 1; idx >= 0; --idx)
		{
			final MenuEntry entry = entries[idx];
			final Widget widget = entry.getWidget();
			if (widget == null || !"Examine".equals(entry.getOption()) || !isStatTooltipWidget(widget))
			{
				continue;
			}

			final int itemId = getItemId(widget);
			if (itemId <= 0)
			{
				return;
			}

			final String name = itemManager.getItemComposition(itemId).getName();
			final ShiftClickAction action = ShiftClickAction.decide(
				isListed(config.alwaysShowItems(), name),
				isAlwaysShown(itemId),
				matchesWithout(config.alwaysShowItems(), name),
				isListed(config.hiddenItems(), name),
				isHidden(itemId),
				matchesWithout(config.hiddenItems(), name),
				isRuleHidden(itemId),
				config.requireHotkey());
			if (action == ShiftClickAction.NONE)
			{
				return;
			}

			client.getMenu().createMenuEntry(idx)
				.setOption(action.showsStats() ? SHOW_OPTION : HIDE_OPTION)
				.setTarget(entry.getTarget())
				.setType(MenuAction.RUNELITE)
				.onClick(e -> apply(action, name));
			return;
		}
	}

	private void apply(ShiftClickAction action, String name)
	{
		switch (action)
		{
			case REMOVE_FROM_HIDDEN:
				editList(ItemStatsFilterConfig.HIDDEN_ITEMS, config.hiddenItems(), name, false);
				break;
			case REMOVE_FROM_HIDDEN_AND_ALWAYS_SHOW:
				editList(ItemStatsFilterConfig.HIDDEN_ITEMS, config.hiddenItems(), name, false);
				editList(ItemStatsFilterConfig.ALWAYS_SHOW_ITEMS, config.alwaysShowItems(), name, true);
				break;
			case ADD_TO_ALWAYS_SHOW:
				editList(ItemStatsFilterConfig.ALWAYS_SHOW_ITEMS, config.alwaysShowItems(), name, true);
				break;
			case REMOVE_FROM_ALWAYS_SHOW:
				editList(ItemStatsFilterConfig.ALWAYS_SHOW_ITEMS, config.alwaysShowItems(), name, false);
				break;
			case REMOVE_FROM_ALWAYS_SHOW_AND_HIDE:
				editList(ItemStatsFilterConfig.ALWAYS_SHOW_ITEMS, config.alwaysShowItems(), name, false);
				editList(ItemStatsFilterConfig.HIDDEN_ITEMS, config.hiddenItems(), name, true);
				break;
			case ADD_TO_HIDDEN:
				editList(ItemStatsFilterConfig.HIDDEN_ITEMS, config.hiddenItems(), name, true);
				break;
			default:
				break;
		}
	}

	HiddenStatsIndicator getIndicator()
	{
		return config.hiddenIndicator();
	}

	boolean isWeightRuleOn()
	{
		return config.ruleWeightOnly();
	}

	boolean showRuleIndicators()
	{
		return config.ruleIndicators();
	}

	/**
	 * Whether hold mode is hiding stats right now.
	 */
	boolean holdModeHides()
	{
		return config.requireHotkey() && !hotkeyHeld;
	}

	/**
	 * Whether the hold key is currently revealing items hidden by the list or a rule.
	 */
	boolean revealsHidden()
	{
		return hotkeyHeld && config.showHiddenOnHold();
	}

	/**
	 * The indicator color for a hiding method, or null for the Grey scheme, where the
	 * indicators keep their original look.
	 */
	Color indicatorColor(HideReason reason)
	{
		final ColorScheme scheme = config.colorScheme();
		if (scheme == ColorScheme.GREY)
		{
			return null;
		}
		if (scheme != ColorScheme.CUSTOM)
		{
			return scheme.color(reason);
		}
		switch (reason)
		{
			case HIDDEN_LIST:
				return config.customHiddenList();
			case RULE:
				return config.customRule();
			default:
				return config.customHold();
		}
	}

	void rememberRuleMatch(int itemId, boolean matches)
	{
		lastRuleItemId = itemId;
		lastRuleMatch = matches;
	}

	private boolean isRuleHidden(int itemId)
	{
		return config.ruleWeightOnly() && lastRuleItemId == itemId && lastRuleMatch;
	}

	/**
	 * The text the Mouse Tooltips plugin shows for the hovered menu entry, built the same
	 * way it builds it, or null if there is nothing to show.
	 */
	String getMouseTooltipText()
	{
		final MenuEntry[] menu = client.getMenu().getMenuEntries();
		if (menu.length == 0)
		{
			return null;
		}

		final MenuEntry entry = menu[menu.length - 1];
		final String option = entry.getOption();
		final String target = entry.getTarget();
		if (option == null || option.isEmpty())
		{
			return null;
		}

		return target == null || target.isEmpty() ? option : option + " " + target;
	}

	/**
	 * A private copy of RuneLite's Item Stats tooltip overlay, reading the Item Stats
	 * plugin's own settings. It is never drawn; {@link ItemStatsFilterOverlay} runs it to
	 * learn exactly which tooltips Item Stats added this frame, so it can remove them.
	 * <p>
	 * The ItemStatConfig binding lives in a private child injector on purpose. RuneLite
	 * builds a plugin's settings panel from the first Config type bound in the plugin's
	 * own injector, so binding it there would replace this plugin's panel with Item Stats'.
	 */
	private ItemStatOverlay createItemStatsProbe()
	{
		final ItemStatConfig itemStatConfig = configManager.getConfig(ItemStatConfig.class);
		return getInjector()
			.createChildInjector(binder -> binder.bind(ItemStatConfig.class).toInstance(itemStatConfig))
			.getInstance(ItemStatOverlay.class);
	}

	/**
	 * Whether this item's name matches the Hidden items list. Client thread only.
	 */
	boolean isHidden(int itemId)
	{
		return matches(itemId, hiddenPatterns, hiddenCache);
	}

	/**
	 * Whether this item's name matches the Always show list. Client thread only.
	 */
	boolean isAlwaysShown(int itemId)
	{
		return matches(itemId, alwaysShowPatterns, alwaysShowCache);
	}

	private boolean matches(int itemId, List<String> patterns, Map<Integer, Boolean> cache)
	{
		if (patterns.isEmpty())
		{
			return false;
		}

		return cache.computeIfAbsent(itemId, id -> matchesAny(patterns, itemManager.getItemComposition(id).getName()));
	}

	private static boolean matchesAny(List<String> patterns, String name)
	{
		for (String pattern : patterns)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether a list would still match this name once its exact-name entries are removed.
	 */
	private static boolean matchesWithout(String csv, String name)
	{
		final List<String> rest = new ArrayList<>(Text.fromCSV(csv));
		rest.removeIf(name::equalsIgnoreCase);
		return matchesAny(rest, name);
	}

	/**
	 * The item under the mouse, found the same way the Item Stats overlay finds it.
	 */
	int getHoveredItemId()
	{
		final MenuEntry[] menu = client.getMenu().getMenuEntries();
		if (menu.length == 0)
		{
			return -1;
		}

		final Widget widget = menu[menu.length - 1].getWidget();
		return widget != null ? getItemId(widget) : -1;
	}

	private static int getItemId(Widget widget)
	{
		final int group = WidgetUtil.componentToInterface(widget.getId());

		// Worn equipment slots keep the item on a child widget
		if (group == InterfaceID.WORNITEMS
			|| (group == InterfaceID.BANKMAIN && widget.getParentId() == InterfaceID.Bankside.WORNOPS))
		{
			final Widget item = widget.getChild(1);
			return item != null ? item.getItemId() : -1;
		}

		return widget.getItemId();
	}

	/**
	 * Places where the Item Stats plugin can show a tooltip.
	 */
	private static boolean isStatTooltipWidget(Widget widget)
	{
		final int group = WidgetUtil.componentToInterface(widget.getId());
		return widget.getId() == InterfaceID.Inventory.ITEMS
			|| group == InterfaceID.WORNITEMS
			|| group == InterfaceID.EQUIPMENT_SIDE
			|| group == InterfaceID.BANKMAIN
			|| group == InterfaceID.BANKSIDE
			|| widget.getId() == InterfaceID.SharedBank.ITEMS
			|| group == InterfaceID.SHARED_BANK_SIDE;
	}

	private static boolean isListed(String csv, String name)
	{
		for (String entry : Text.fromCSV(csv))
		{
			if (entry.equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}

	private void editList(String key, String csv, String name, boolean add)
	{
		final List<String> items = new ArrayList<>(Text.fromCSV(csv));
		items.removeIf(name::equalsIgnoreCase);
		if (add)
		{
			items.add(name);
		}
		configManager.setConfiguration(ItemStatsFilterConfig.GROUP, key, Text.toCSV(items));
	}

	private void updateHiddenPatterns()
	{
		hiddenPatterns = Text.fromCSV(config.hiddenItems());
		hiddenCache.clear();
	}

	private void updateAlwaysShowPatterns()
	{
		alwaysShowPatterns = Text.fromCSV(config.alwaysShowItems());
		alwaysShowCache.clear();
	}

	/**
	 * Whether holding the key currently does anything.
	 */
	private boolean wantsHotkey()
	{
		return config.requireHotkey()
			|| (config.showHiddenOnHold() && (!hiddenPatterns.isEmpty() || config.ruleWeightOnly()));
	}

	private synchronized void updateHotkeyListener()
	{
		if (hotkeyListener != null)
		{
			keyManager.unregisterKeyListener(hotkeyListener);
			hotkeyListener = null;
		}
		hotkeyHeld = false;

		// Only listen while the key does something, so a bound key isn't swallowed otherwise
		if (wantsHotkey())
		{
			hotkeyListener = new HotkeyListener(config::hotkey)
			{
				@Override
				public void hotkeyPressed()
				{
					hotkeyHeld = true;
				}

				@Override
				public void hotkeyReleased()
				{
					hotkeyHeld = false;
				}
			};
			keyManager.registerKeyListener(hotkeyListener);
		}
	}
