package com.itemstatsfilter;

/**
 * What a shift-click "Hide stats" / "Show stats" option does for an item. Each option
 * always gets the item to the state its label promises in one click.
 */
enum ShiftClickAction
{
	/** No option: the item is shown or hidden by a wildcard entry, which has to be edited by hand. */
	NONE,
	/** Show stats: take the item off Hidden items. */
	REMOVE_FROM_HIDDEN,
	/** Show stats: take it off Hidden items and, since something else still hides it, add it to Always show. */
	REMOVE_FROM_HIDDEN_AND_ALWAYS_SHOW,
	/** Show stats: the item is hidden by a wildcard, a rule or hold mode, so add it to Always show. */
	ADD_TO_ALWAYS_SHOW,
	/** Hide stats: take the item off Always show; something else then hides it. */
	REMOVE_FROM_ALWAYS_SHOW,
	/** Hide stats: take it off Always show and, since nothing else would hide it, add it to Hidden items. */
	REMOVE_FROM_ALWAYS_SHOW_AND_HIDE,
	/** Hide stats: the item is showing and on neither list, so add it to Hidden items. */
	ADD_TO_HIDDEN;

	boolean showsStats()
	{
		return this == REMOVE_FROM_HIDDEN || this == REMOVE_FROM_HIDDEN_AND_ALWAYS_SHOW || this == ADD_TO_ALWAYS_SHOW;
	}

	/**
	 * @param alwaysByName      the item's exact name is on Always show
	 * @param alwaysMatched     Always show matches the item, by name or wildcard
	 * @param alwaysWithoutName Always show would still match once the exact name is removed
	 * @param hiddenByName      the item's exact name is on Hidden items
	 * @param hiddenMatched     Hidden items matches the item, by name or wildcard
	 * @param hiddenWithoutName Hidden items would still match once the exact name is removed
	 * @param ruleHidden        a ticked rule hides the item
	 * @param holdHidden        Only show item stats on hold is on
	 */
	static ShiftClickAction decide(boolean alwaysByName, boolean alwaysMatched, boolean alwaysWithoutName,
		boolean hiddenByName, boolean hiddenMatched, boolean hiddenWithoutName,
		boolean ruleHidden, boolean holdHidden)
	{
		if (alwaysMatched)
		{
			if (!alwaysByName || alwaysWithoutName)
			{
				return NONE;
			}
			final boolean otherwiseHidden = hiddenMatched || ruleHidden || holdHidden;
			return otherwiseHidden ? REMOVE_FROM_ALWAYS_SHOW : REMOVE_FROM_ALWAYS_SHOW_AND_HIDE;
		}

		if (hiddenByName)
		{
			final boolean stillHidden = hiddenWithoutName || ruleHidden || holdHidden;
			return stillHidden ? REMOVE_FROM_HIDDEN_AND_ALWAYS_SHOW : REMOVE_FROM_HIDDEN;
		}

		if (hiddenMatched || ruleHidden || holdHidden)
		{
			return ADD_TO_ALWAYS_SHOW;
		}

		return ADD_TO_HIDDEN;
	}
}

